Lemma dl_from_Q0 : forall j Σk b ib ents rest, ents <> [] -> rt_wfP Σk ((b, ents) :: rest) -> dl_sig p Σk ->
  nth_error (r_st (pr Σk 24)) ib = Some CkBatch -> b = p_abeg (l_SB (lay Σk)) 24 ib ->
  cps asegs (ASTA RTA Σk PMc (dl_Q p j b ents 0 rest Σk))
